import{_ as t,o as e,c as o,Q as r}from"./chunks/framework.b67c47e6.js";const f=JSON.parse('{"title":"Wood BoM","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/wood_bom/index.md","filePath":"guide/reports/wood_bom/index.md","lastUpdated":1790336709000}'),a={name:"guide/reports/wood_bom/index.md"},n=r('<h1 id="wood-bom" tabindex="-1">Wood BoM <a class="header-anchor" href="#wood-bom" aria-label="Permalink to &quot;Wood BoM&quot;">​</a></h1><p>The Wood Bill of Materials generates a PDF document listing all wood and profile parts for your selected constructibles.</p><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> PDF (single file or ZIP with multiple PDFs)</li><li><strong>Content:</strong> All wood/profile parts with dimensions, quantities, materials, and optional cross-section drawings.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Grouping</strong></td><td>Choose how parts are organized: all in one document, grouped by batch, or one per assembly.</td></tr><tr><td><strong>Cover page</strong></td><td>Include a title page with project information.</td></tr><tr><td><strong>Designs summary</strong></td><td>Add a summary table listing all included designs.</td></tr><tr><td><strong>Materials totals page</strong></td><td>Append a page with total material quantities (linear meters per material type).</td></tr><tr><td><strong>Show profile side drawings</strong></td><td>Include wood profile cross-section drawings.</td></tr><tr><td><strong>Group parts that differ only in length</strong></td><td>On by default. Parts with the same details and a different length share one table and one drawing, with the length shown as LENGTH. See <a href="#parts-that-differ-only-in-length">below</a>.</td></tr><tr><td><strong>Cross-section filter</strong></td><td>Filter by specific cross-section types.</td></tr><tr><td><strong>Table style</strong></td><td>Choose between &quot;Extended tables&quot; or &quot;Classic tables&quot; layout.</td></tr><tr><td><strong>Combine</strong></td><td>When grouping by batch or assembly, merge all PDFs into one combined file.</td></tr><tr><td><strong>Attach to viewer</strong></td><td>Link the generated PDF to the assembly in the 3D Viewer.</td></tr><tr><td><strong>Filter by material</strong></td><td>Only include wood parts of specific material types.</td></tr></tbody></table><h2 id="parts-that-differ-only-in-length" tabindex="-1">Parts that differ only in length <a class="header-anchor" href="#parts-that-differ-only-in-length" aria-label="Permalink to &quot;Parts that differ only in length&quot;">​</a></h2><p>With <strong>Show profile side drawings</strong> on, each wood part with a detail (a drilling, a notch, an angled end cut) gets a table and a drawing of its own. When several parts have exactly the same details and differ only in their length — the studs of a sloped wall, all with the same angled top cut — they now share <strong>one table and one drawing</strong>, with a row per part.</p><ul><li>The drawing shows the length as <strong>LENGTH</strong>, with no number. The real length of each part is in its row.</li><li>The part of the length that changes is drawn short, between two break marks.</li><li>Details before it are measured from the left end, below the drawing. Details after it are measured from the right end, above the drawing, each end with its own 0.</li><li>Only the length may differ: a different width, height, section, material, finish or comment keeps the parts apart. Details must match within 1 mm.</li><li>A part turned end for end or turned over counts as the same part. A mirrored part does not.</li><li>A group has <strong>one</strong> changing length or none. If some parts change before a detail and others after it, they form separate groups.</li></ul><p>Turn it off with <strong>Group parts that differ only in length</strong> to get one table per part again. The drawing of each part, in the viewer and in logistics, is not affected: it keeps all its numbers.</p><h2 id="grouping-modes" tabindex="-1">Grouping Modes <a class="header-anchor" href="#grouping-modes" aria-label="Permalink to &quot;Grouping Modes&quot;">​</a></h2><ul><li><strong>Selected</strong> — One single PDF with all selected content.</li><li><strong>Batch</strong> — One PDF per batch (ZIP output).</li><li><strong>Panels</strong> — One PDF per assembly (ZIP output).</li></ul>',12),i=[n];function s(d,l,h,g,p,c){return e(),o("div",null,i)}const m=t(a,[["render",s]]);export{f as __pageData,m as default};
